import numpy as np


def causal_mask(seq_len):
    """Lower-triangular boolean mask: True where a token may attend."""
    return np.tril(np.ones((seq_len, seq_len), dtype=bool))


def apply_mask(scores, mask):
    """Set scores to -1e9 where the mask is False."""
    return np.where(mask, scores, -1e9)


if __name__ == "__main__":
    m = causal_mask(4)
    print(m)
    print(apply_mask(np.zeros((4, 4)), m))
